// src/calculators/TvmCalculator.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import TvmSearchFom from './TvmSearchForm';
import TvmResultFom from './TvmResult';

export default function TvmCalculator() {
  const navigate = useNavigate();
  const [selectedPlan, setSelectedPlan] = useState(null);

  return (
    <div className="p-6 max-w-3xl mx-auto">
      {/* 타이틀 */}
      <h1 className="text-3xl font-bold mb-8 text-center">
        KT TV 계산기
      </h1>

      {/* 검색 폼 또는 결과 */}
      {!selectedPlan ? (
        <TvmSearchFom onSelect={setSelectedPlan} />
      ) : (
        <>
          {/* 선택된 플랜 결과 */}
          <TvmResultFom plan={selectedPlan} />

          {/* 액션 버튼 그룹 */}
          <div className="flex flex-col items-center space-y-4 mb-8">
            {/* 결합하기 버튼 */}
            <button
              type="button"
              onClick={() => navigate('/bundle')}
              className="w-48 bg-indigo-600 text-white rounded py-2 hover:bg-indigo-700 transition"
            >
              결합하기
            </button>

            {/* 다른 플랜 검색하기 버튼 */}
            <button
              type="button"
              onClick={() => setSelectedPlan(null)}
              className="w-48 bg-blue-500 text-white rounded py-2 hover:bg-blue-600 transition"
            >
              다른 플랜 검색하기
            </button>
          </div>
        </>
      )}

      {/* 메인으로 돌아가기 버튼 */}
      <button
        type="button"
        onClick={() => navigate('/')}
        className="block mx-auto bg-gray-200 text-gray-700 rounded py-2 px-4 hover:bg-gray-300 transition"
      >
        메인으로 돌아가기
      </button>
    </div>
  );
}
