// src/calculators/TvmResult.jsx
import React from 'react';

/**
 * plan.pricing 객체를 테이블로 렌더링
 */
export default function TvmResult({ plan }) {
  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">
        선택된 플랜 : {plan.name} ({plan.channel}채널)
      </h2>
      <table className="w-full table-auto border-collapse">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-3 py-2">약정 기간</th>
            {Object.keys(plan.pricing).map(term => (
              <th key={term} className="border px-3 py-2">
                {term}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          <tr>
            <td className="border px-3 py-2">월 요금(원)</td>
            {Object.values(plan.pricing).map((price, i) => (
              <td key={i} className="border px-3 py-2">
                {price.toLocaleString()}
              </td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}
